import java.text.Normalizer;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.function.Predicate;
import java.util.regex.Pattern;

/**
 * Which customers a list shows: a name search and a set of statuses.
 *
 * <p>A customer matches when it satisfies both parts:
 * <ul>
 *   <li>every whitespace-separated term of the name appears, ignoring case and
 *       accents, in the customer's first name or last name;</li>
 *   <li>the customer has one of the statuses, or no statuses are given.</li>
 * </ul>
 *
 * @param name     the text typed into the name filter; blank matches every name
 * @param statuses the statuses to keep; empty keeps every status
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    /** The filter that keeps every customer. */
    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());

    private static final Pattern WHITESPACE = Pattern.compile("\\s+", Pattern.UNICODE_CHARACTER_CLASS);
    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}+");

    public CustomerFilter {
        name = name.strip();
        statuses = Set.copyOf(statuses);
    }

    /**
     * Returns a predicate that accepts the customers this filter keeps. The name
     * terms are worked out once here rather than once per customer.
     */
    public Predicate<Customer> matcher() {
        List<String> terms = WHITESPACE.splitAsStream(fold(name))
                .filter(term -> !term.isEmpty())
                .toList();
        return customer -> (statuses.isEmpty() || statuses.contains(customer.status()))
                && nameMatches(customer, terms);
    }

    private static boolean nameMatches(Customer customer, List<String> terms) {
        String first = fold(customer.firstName());
        String last = fold(customer.lastName());
        return terms.stream().allMatch(term -> first.contains(term) || last.contains(term));
    }

    /** Lower-cases and strips accents, so that "Mäkinen", "MAKINEN" and "makinen" compare equal. */
    private static String fold(String text) {
        String lowered = text.toLowerCase(Locale.ROOT);
        return COMBINING_MARKS.matcher(Normalizer.normalize(lowered, Normalizer.Form.NFD)).replaceAll("");
    }
}
