/**
 * Drives the running application in a real browser, to check what the browserless
 * test cannot see: the address bar, the history, and what typing costs the backend.
 */
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class CustomerListBrowserTest extends AbstractBasePlaywrightIT {

    @LocalServerPort
    private int port;

    @Autowired
    private QueryLog queryLog;

    @Override
    public String getUrl() {
        return "http://localhost:" + port + "/";
    }

    private Locator nameField() {
        return page.getByPlaceholder("Filter by name");
    }

    @Test
    void typingNarrowsTheListWithoutPressingEnter() {
        queryLog.clear();
        int historyBefore = (Integer) page.evaluate("history.length");

        nameField().pressSequentially("makinen");

        assertThat(page.getByText("Showing 15 of 500")).isVisible();
        assertThat(page).hasURL(Pattern.compile(".*/\\?name=makinen$"));

        // Typing a word is a pause-separated change: one count, one page for the
        // rows on screen. Not one query per letter.
        assertTrue(queryLog.countQueries().size() <= 2,
                "Typing one word ran " + queryLog.countQueries().size() + " count queries");
        assertTrue(queryLog.pageQueries().size() <= 2,
                "Typing one word ran " + queryLog.pageQueries().size() + " page queries");

        int historyAfter = (Integer) page.evaluate("history.length");
        assertEquals(historyBefore, historyAfter, "Typing must not add history entries");
    }

    @Test
    void clearingTheFilterRemovesTheParameters() {
        nameField().pressSequentially("ada aal");
        assertThat(page).hasURL(Pattern.compile(".*/\\?name=ada%20aal$"));

        nameField().fill("");

        assertThat(page.getByText("Showing 500 of 500")).isVisible();
        assertThat(page).hasURL(Pattern.compile(".*/$"));
    }

    @Test
    void openingWithAFilterInTheAddressBarAppliesIt() {
        page.navigate(getUrl() + "?name=vir&status=ACTIVE,CLOSED");

        assertThat(page.getByText("Showing 10 of 500")).isVisible();
        assertThat(nameField()).hasValue("vir");
        assertThat(page).hasURL(Pattern.compile(".*/\\?name=vir&status=ACTIVE,CLOSED$"));
    }
}
