+        if (!filter.statuses().isEmpty()) {
+            parameters.add("status=" + filter.statuses().stream().sorted()
+                    .map(CustomerStatus::name)
+                    .collect(Collectors.joining(",")));
+        }
+        return parameters.isEmpty() ? "" : "?" + String.join("&", parameters);
+    }
+
+    private static String encode(String value) {
+        // URLEncoder writes a space as '+'; the address bar shows %20, as Vaadin does.
+        return URLEncoder.encode(value, StandardCharsets.UTF_8).replace("+", "%20");
+    }
+
+    /** The statuses named in a comma-separated parameter. Names that are not statuses are ignored. */
+    static Set<CustomerStatus> statusesNamed(String parameter) {
+        Set<String> names = Arrays.stream(parameter.split(","))
+                .map(name -> name.strip().toUpperCase(Locale.ROOT))
+                .collect(Collectors.toSet());
+        return Arrays.stream(CustomerStatus.values())
+                .filter(status -> names.contains(status.name()))
+                .collect(Collectors.toSet());
     }

