+
+import com.example.customers.domain.QueryLog;
+
+import com.microsoft.playwright.Locator;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+import org.vaadin.addons.dramafinder.element.MultiSelectComboBoxElement;
+
+/**
+ * Drives the running application in a real browser. This is where the address
+ * bar, the browser history and the cost of typing can be seen; the browserless
+ * test cannot see them.
+ */
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class CustomerListBrowserIT extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Autowired
+    private QueryLog queryLog;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/";
+    }
+
+    /** The input inside the field. The field element also carries the placeholder, so match the input only. */
+    private Locator nameField() {
+        return page.locator("input[slot='input'][placeholder='Filter by name']");
+    }
+
+    /** Typing a word applies it without Enter, costs one count and one page query, and adds no history entry. */
+    @Test
+    void typingNarrowsTheListWithoutPressingEnter() {
+        queryLog.clear();
+        int historyBefore = (Integer) page.evaluate("history.length");
+
+        nameField().pressSequentially("makinen");
+
+        assertThat(page.getByText("Showing 15 of 500")).isVisible();
+        assertThat(page).hasURL(Pattern.compile(".*/\\?name=makinen$"));
+        assertEquals(1, queryLog.countQueries().size(),
+                "Typing a word must count the matches once, not once per letter");
+        assertEquals(1, queryLog.pageQueries().size(),
+                "Typing a word must fetch the rows on screen once, not once per letter");
+
+        int historyAfter = (Integer) page.evaluate("history.length");
+        assertEquals(historyBefore, historyAfter, "Typing must not add history entries");
+    }
+
+    /** A short pause between letters is still one word, not one query per letter. */
+    @Test
+    void slowTypingIsStillOneQuery() {
+        queryLog.clear();
+
+        nameField().pressSequentially("makinen", new Locator.PressSequentiallyOptions().setDelay(100));
+
+        assertThat(page.getByText("Showing 15 of 500")).isVisible();
+        assertTrue(queryLog.countQueries().size() <= 2,
+                "Typing a word ran " + queryLog.countQueries().size() + " count queries");
+        assertTrue(queryLog.pageQueries().size() <= 2,
+                "Typing a word ran " + queryLog.pageQueries().size() + " page queries");
+    }
+
+    /** Choosing statuses writes them into the address bar, with the comma between them unescaped. */
+    @Test
+    void selectingStatusesWritesThemIntoTheAddressBar() {
+        var status = new MultiSelectComboBoxElement(page.locator("vaadin-multi-select-combo-box"));
+
+        status.selectItems("ACTIVE", "CLOSED");
+
+        assertThat(page.getByText("Showing 333 of 500")).isVisible();
+        assertThat(page).hasURL(Pattern.compile(".*/\\?status=ACTIVE,CLOSED$"));
+    }
+
+    @Test
+    void clearingTheFilterRemovesTheParameters() {
+        nameField().pressSequentially("ada aal");
+        assertThat(page).hasURL(Pattern.compile(".*/\\?name=ada%20aal$"));
+
+        nameField().fill("");
+
+        assertThat(page.getByText("Showing 500 of 500")).isVisible();
+        assertThat(page).hasURL(Pattern.compile(".*/$"));
+    }
+
+    @Test
+    void openingWithAFilterInTheAddressBarAppliesIt() {
+        page.navigate(getUrl() + "?name=vir&status=ACTIVE,CLOSED");
+
+        assertThat(page.getByText("Showing 10 of 500")).isVisible();
+        assertThat(nameField()).hasValue("vir");
+        assertThat(page).hasURL(Pattern.compile(".*/\\?name=vir&status=ACTIVE,CLOSED$"));
+    }
+}
